 for(let d of drops){let visible=d.status==='ready';d.sprite.setVisible(visible).setY(297+Math.sin(t*2.5)*7);d.label.setText(d.status==='earned'?'UNLOCKED':'×'+d.n+' SHOT').setAlpha(d.status==='cooldown'?.28:d.status==='earned'?.5:1);g.fillStyle(0x192c3d);g.fillRect(d.x-28,345,56,13);g.fillStyle(0x759394);g.fillRect(d.x-31,342,62,4);if(visible){g.lineStyle(1,C[d.n],.6);g.strokeEllipse(d.x,300,70,53);g.fillStyle(C[d.n],.06);g.fillCircle(d.x,300,43);for(let i=0;i<4;i++){let a=t*1.7+i*Math.PI/2;g.fillStyle(C[d.n],.8);g.fillRect(d.x+Math.cos(a)*34,300+Math.sin(a)*24,3,3)}}}
